<?php

declare(strict_types=1);

require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/content.php';

header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: no-store, max-age=0');
header('Pragma: no-cache');
header('X-Content-Type-Options: nosniff');
header('X-Frame-Options: DENY');
header('Referrer-Policy: no-referrer');
header('X-Robots-Tag: noindex, nofollow, noarchive');
header("Content-Security-Policy: default-src 'self'; style-src 'unsafe-inline'; img-src 'self' data:; base-uri 'none'; form-action 'self'; frame-ancestors 'none'");

const ASTREA_EDITOR_SECTIONS = ['overview', 'news', 'materials', 'events', 'pages'];

function e(mixed $value): string { return htmlspecialchars((string)$value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function redirect_editor(string $section='overview', array $query=[]): never {
    $params = $section === 'overview' ? $query : ['section'=>$section] + $query;
    $url = '/editor/' . ($params === [] ? '' : '?' . http_build_query($params));
    header('Location: ' . $url, true, 303); exit;
}
function editor_section(): string {
    $section = is_string($_GET['section'] ?? null) ? $_GET['section'] : 'overview';
    return in_array($section, ASTREA_EDITOR_SECTIONS, true) ? $section : 'overview';
}
function positive_id(mixed $value): int { $id=(int)$value; if($id<1) throw new InvalidArgumentException('Запись не найдена.'); return $id; }
function overview_counts(PDO $db): array {
    $queries=['news'=>'SELECT COUNT(*) FROM news','materials'=>'SELECT COUNT(*) FROM materials','events'=>'SELECT COUNT(*) FROM events','pages'=>'SELECT COUNT(*) FROM pages'];$out=[];
    foreach($queries as $key=>$sql)$out[$key]=(int)$db->query($sql)->fetchColumn(); return $out;
}
function editor_validation_error(string $message): void {
    $code=http_response_code();
    if(!is_int($code)||$code<400) http_response_code(422);
    $GLOBALS['error']=$message;
}

$error=null; $statusMessage=null; $db=null;
try {
    astrea_editor_start_session(); $db=astrea_db();
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
        $action=is_string($_POST['action']??null)?$_POST['action']:'';
        if($action==='login'&&!astrea_editor_is_authenticated()){
            $username=is_string($_POST['username']??null)?$_POST['username']:'';$password=is_string($_POST['password']??null)?$_POST['password']:'';
            $result=astrea_editor_authenticate($db,$username,$password,astrea_editor_client_key($_SERVER['REMOTE_ADDR']??null));
            if($result['ok']===true&&is_array($result['user'])){astrea_editor_login_session($result['user']);redirect_editor();}
            $error=$result['blocked']===true?'Слишком много неудачных попыток. Попробуйте позже.':'Неверное имя пользователя или пароль.';
        } elseif($action==='logout'&&astrea_editor_is_authenticated()){
            if(!astrea_editor_verify_csrf($_POST['csrf_token']??null)){http_response_code(403);$error='Сессия формы устарела. Обновите страницу и повторите действие.';}
            else{astrea_editor_logout_session();redirect_editor();}
        } elseif(astrea_editor_is_authenticated()){
            if(!astrea_editor_verify_csrf($_POST['csrf_token']??null)){http_response_code(403);throw new InvalidArgumentException('Сессия формы устарела. Обновите страницу и повторите действие.');}
            if($action==='save_news'){ $id=astrea_editor_save_news($db,$_POST); redirect_editor('news',['saved'=>$id]); }
            if($action==='delete_news'){ if(($_POST['confirm_delete']??null)!=='1')throw new InvalidArgumentException('Подтвердите удаление.'); astrea_editor_delete_news($db,positive_id($_POST['id']??0));redirect_editor('news',['deleted'=>1]); }
            if($action==='save_material'){ $id=astrea_editor_save_material($db,$_POST);redirect_editor('materials',['saved'=>$id]); }
            if($action==='delete_material'){ if(($_POST['confirm_delete']??null)!=='1')throw new InvalidArgumentException('Подтвердите удаление.');astrea_editor_delete_material($db,positive_id($_POST['id']??0));redirect_editor('materials',['deleted'=>1]); }
            if($action==='save_event'){ $id=astrea_editor_save_event($db,$_POST);redirect_editor('events',['saved'=>$id]); }
            if($action==='delete_event'){ if(($_POST['confirm_delete']??null)!=='1')throw new InvalidArgumentException('Подтвердите удаление.');astrea_editor_delete_event($db,positive_id($_POST['id']??0));redirect_editor('events',['deleted'=>1]); }
            if($action==='save_page'){ $key=astrea_editor_save_page($db,$_POST);redirect_editor('pages',['saved'=>$key]); }
            throw new InvalidArgumentException('Некорректный запрос.');
        } else { http_response_code(400);$error='Некорректный запрос.'; }
    }
} catch(InvalidArgumentException $ex){ editor_validation_error($ex->getMessage()); }
catch(Throwable){ http_response_code(503);$db=null;$error='Редактор временно недоступен. Проверьте конфигурацию хостинга.'; }

$authenticated=astrea_editor_is_authenticated();$csrfToken=$authenticated?astrea_editor_csrf_token():null;$username=$authenticated?astrea_editor_username():null;$section=editor_section();
if($authenticated&&isset($_GET['saved']))$statusMessage='Изменения сохранены.'; if($authenticated&&isset($_GET['deleted']))$statusMessage='Запись удалена.';
$counts=[];$news=$materials=$events=$pages=[];$edit=null;
if($authenticated&&$db instanceof PDO){
    try {
        $counts=overview_counts($db);
        if($section==='news'){
            $news=astrea_editor_list_news($db);
            if(isset($_GET['edit'])){ $edit=astrea_editor_get_news($db,positive_id($_GET['edit'])); if($edit===null)throw new InvalidArgumentException('Новость не найдена.'); }
        }
        elseif($section==='materials'){
            $materials=astrea_editor_list_materials($db);
            if(isset($_GET['edit'])){ $edit=astrea_editor_get_material($db,positive_id($_GET['edit'])); if($edit===null)throw new InvalidArgumentException('Материал не найден.'); }
        }
        elseif($section==='events'){
            $events=astrea_editor_list_events($db);
            if(isset($_GET['edit'])){ $edit=astrea_editor_get_event($db,positive_id($_GET['edit'])); if($edit===null)throw new InvalidArgumentException('Событие не найдено.'); }
        }
        elseif($section==='pages'){
            $pages=astrea_editor_list_pages($db);
            if(isset($_GET['edit'])&&is_string($_GET['edit'])){ $edit=astrea_editor_get_page($db,$_GET['edit']); if($edit===null)throw new InvalidArgumentException('Страница не найдена.'); }
        }
    } catch(InvalidArgumentException $ex){ editor_validation_error($ex->getMessage()); $edit=null; }
    catch(Throwable){ http_response_code(503);$db=null;$error='Редактор временно недоступен. Проверьте конфигурацию хостинга.'; }
}
?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Astrea Lite Editor</title>
<style>
:root{color-scheme:dark;--bg:#071019;--panel:#0d1822;--line:#29404f;--text:#eef2f4;--muted:#9aa8b2;--red:#9b1c2f;--red2:#ba2740;--gold:#b9a471}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:linear-gradient(180deg,#050c12,#09141d);color:var(--text);font-family:Arial,Helvetica,sans-serif}a{color:inherit}.wrap{width:min(1180px,calc(100% - 32px));margin:0 auto}.top{border-bottom:1px solid var(--line);background:#050b10}.topin{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand small{display:block;color:var(--gold);letter-spacing:.18em;text-transform:uppercase;font-size:11px}.brand strong{display:block;margin-top:5px;font:400 27px/1.1 "Times New Roman",Times,serif}.user{display:flex;align-items:center;gap:12px;color:var(--muted);font-size:14px}main{padding:34px 0 60px}.login,.panel{border:1px solid var(--line);background:var(--panel)}.login{width:min(470px,100%);margin:8vh auto 0;padding:30px}h1,h2,h3{font-family:"Times New Roman",Times,serif;font-weight:400}h1{font-size:34px;margin:0}h2{font-size:24px;margin:0}h3{font-size:20px;margin:0}.lead,.muted{color:var(--muted);line-height:1.55}.toolbar{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:22px}.nav{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 24px}.nav a{padding:10px 13px;border:1px solid var(--line);text-decoration:none;font-size:14px}.nav a.active{border-color:var(--red2);background:#261018}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.card{border:1px solid var(--line);background:var(--panel);padding:20px;min-height:142px}.num{font:400 40px/1 "Times New Roman",Times,serif;margin-top:24px}.card p{margin:7px 0 0;color:var(--muted);font-size:13px}.split{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(340px,.85fr);gap:18px}.panel{padding:20px}.list{display:grid;gap:10px;margin-top:16px}.row{border:1px solid var(--line);padding:14px;display:flex;justify-content:space-between;gap:16px;align-items:center}.row strong{display:block}.row small{display:block;color:var(--muted);margin-top:5px}.row .state{font-size:12px;color:var(--muted)}label{display:block;margin:14px 0 6px;color:#dbe2e6;font-size:14px}input,textarea,select{width:100%;border:1px solid var(--line);background:#071019;color:var(--text);padding:11px 12px;font-size:15px;outline:none}textarea{min-height:110px;resize:vertical}textarea.large{min-height:240px}input:focus,textarea:focus,select:focus{border-color:#d8dee2;box-shadow:0 0 0 2px rgba(255,255,255,.07)}button,.button{display:inline-flex;align-items:center;justify-content:center;border:1px solid var(--red2);background:var(--red);color:#fff;padding:10px 14px;cursor:pointer;font-weight:700;text-decoration:none}.ghost{background:transparent;border-color:var(--line)}.danger{background:#3a1118;border-color:#8e3340}.actions{margin-top:18px;display:flex;flex-wrap:wrap;gap:10px}.check{display:flex;align-items:center;gap:9px;margin-top:14px}.check input{width:auto}.error,.notice{margin:0 0 18px;padding:12px 14px;line-height:1.45}.error{border:1px solid #74303a;background:#291017;color:#ffd9df}.notice{border:1px solid #395949;background:#10251b;color:#d9f5e4}.deletebox{border-top:1px solid var(--line);margin-top:22px;padding-top:18px}.empty{color:var(--muted);padding:18px 0}.type{color:var(--gold);font-size:12px;text-transform:uppercase;letter-spacing:.08em}
@media(max-width:900px){.split{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.topin,.toolbar{align-items:flex-start;flex-direction:column;padding:18px 0}.user{width:100%;justify-content:space-between}}@media(max-width:480px){.grid{grid-template-columns:1fr}.wrap{width:min(100% - 22px,1180px)}.login,.panel{padding:18px}.row{align-items:flex-start;flex-direction:column}}
</style></head><body>
<header class="top"><div class="wrap topin"><div class="brand"><small>Astrea</small><strong>Lite Editor</strong></div><?php if($authenticated):?><div class="user"><span><?=e($username)?></span><form method="post" action="/editor/"><input type="hidden" name="action" value="logout"><input type="hidden" name="csrf_token" value="<?=e($csrfToken)?>"><button class="ghost" type="submit">Выйти</button></form></div><?php endif;?></div></header>
<main class="wrap">
<?php if(!$authenticated):?><section class="login"><h1>Вход в редактор</h1><p class="lead">Управление новостями, материалами, календарём и страницами ложи.</p><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><form method="post" action="/editor/"><input type="hidden" name="action" value="login"><label>Имя пользователя</label><input name="username" maxlength="120" autocomplete="username" required><label>Пароль</label><input name="password" type="password" autocomplete="current-password" required><div class="actions"><button>Войти</button></div></form></section>
<?php else:?><div class="toolbar"><div><h1>Панель управления</h1><p class="muted">Изменения публикуются без GitHub и пересборки сайта.</p></div></div><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><?php if($statusMessage):?><div class="notice"><?=e($statusMessage)?></div><?php endif;?>
<nav class="nav" aria-label="Разделы редактора"><?php foreach(['overview'=>'Обзор','news'=>'Новости','materials'=>'Материалы','events'=>'События','pages'=>'Страницы'] as $key=>$label):?><a class="<?=$section===$key?'active':''?>" href="/editor/<?=$key==='overview'?'':'?section='.e($key)?>"><?=e($label)?></a><?php endforeach;?></nav>
<?php if($section==='overview'):?><section class="grid"><article class="card"><h2>Новости</h2><div class="num"><?=(int)($counts['news']??0)?></div><p>Всего записей</p></article><article class="card"><h2>Материалы</h2><div class="num"><?=(int)($counts['materials']??0)?></div><p>Книги, видео, аудио, статьи</p></article><article class="card"><h2>События</h2><div class="num"><?=(int)($counts['events']??0)?></div><p>Даты работ и мероприятий</p></article><article class="card"><h2>Страницы</h2><div class="num"><?=(int)($counts['pages']??0)?></div><p>Фиксированные страницы</p></article></section>
<?php elseif($section==='news'):?><div class="split"><section class="panel"><h2>Новости</h2><p class="muted">Создавайте черновики и публикуйте готовые новости.</p><div class="actions"><a class="button" href="/editor/?section=news&new=1">Добавить новость</a></div><div class="list"><?php foreach($news as $row):?><div class="row"><div><strong><?=e($row['title'])?></strong><small>/novosti/<?=e($row['slug'])?></small></div><div><span class="state"><?=((int)$row['is_published']===1)?'Опубликована':'Черновик'?></span> · <a href="/editor/?section=news&edit=<?=(int)$row['id']?>">Изменить</a></div></div><?php endforeach;?><?php if($news===[]):?><div class="empty">Новостей пока нет.</div><?php endif;?></div></section><section class="panel"><?php $v=is_array($edit)?$edit:[];?><h2><?=is_array($edit)?'Редактировать новость':'Новая новость'?></h2><form method="post" action="/editor/?section=news"><input type="hidden" name="action" value="save_news"><input type="hidden" name="csrf_token" value="<?=e($csrfToken)?>"><input type="hidden" name="id" value="<?=(int)($v['id']??0)?>"><label>Slug</label><input name="slug" maxlength="160" value="<?=e($v['slug']??'')?>" placeholder="novost-lozhi" required><label>Заголовок</label><input name="title" maxlength="255" value="<?=e($v['title']??'')?>" required><label>Краткое описание</label><textarea name="excerpt" required><?=e($v['excerpt']??'')?></textarea><label>Текст</label><textarea class="large" name="body" required><?=e($v['body']??'')?></textarea><label>HTTPS-ссылка на изображение (необязательно)</label><input name="image_url" maxlength="500" value="<?=e($v['image_url']??'')?>"><label class="check"><input type="checkbox" name="is_published" value="1" <?=((int)($v['is_published']??0)===1)?'checked':''?>> Опубликовано</label><div class="actions"><button>Сохранить</button></div></form><?php if(is_array($edit)):?><form class="deletebox" method="post" action="/editor/?section=news"><input type="hidden" name="action" value="delete_news"><input type="hidden" name="csrf_token" value="<?=e($csrfToken)?>"><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><label class="check"><input type="checkbox" name="confirm_delete" value="1" required> Подтверждаю удаление</label><div class="actions"><button class="danger">Удалить новость</button></div></form><?php endif;?></section></div>
<?php elseif($section==='materials'):?><div class="split"><section class="panel"><h2>Материалы</h2><p class="muted">Книги, видео RuTube, аудио и статьи в одной коллекции.</p><div class="actions"><a class="button" href="/editor/?section=materials&new=1">Добавить материал</a></div><div class="list"><?php foreach($materials as $row):?><div class="row"><div><span class="type"><?=e($row['material_type'])?></span><strong><?=e($row['title'])?></strong><small><?=e($row['slug'])?></small></div><div><span class="state"><?=((int)$row['is_published']===1)?'Опубликован':'Черновик'?></span> · <a href="/editor/?section=materials&edit=<?=(int)$row['id']?>">Изменить</a></div></div><?php endforeach;?><?php if($materials===[]):?><div class="empty">Материалов пока нет.</div><?php endif;?></div></section><section class="panel"><?php $v=is_array($edit)?$edit:[];?><h2><?=is_array($edit)?'Редактировать материал':'Новый материал'?></h2><form method="post" action="/editor/?section=materials"><input type="hidden" name="action" value="save_material"><input type="hidden" name="csrf_token" value="<?=e($csrfToken)?>"><input type="hidden" name="id" value="<?=(int)($v['id']??0)?>"><label>Тип</label><select name="material_type" required><?php foreach(['book'=>'Книга','video'=>'Видео','audio'=>'Аудио','article'=>'Статья'] as $key=>$label):?><option value="<?=e($key)?>" <?=($v['material_type']??'book')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><label>Slug</label><input name="slug" maxlength="160" value="<?=e($v['slug']??'')?>" required><label>Название</label><input name="title" maxlength="255" value="<?=e($v['title']??'')?>" required><label>Краткое описание</label><textarea name="excerpt" required><?=e($v['excerpt']??'')?></textarea><label>Основной текст (необязательно)</label><textarea class="large" name="body"><?=e($v['body']??'')?></textarea><label>Автор (необязательно)</label><input name="author" maxlength="255" value="<?=e($v['author']??'')?>"><label>HTTPS-ссылка на источник / RuTube</label><input name="source_url" maxlength="1000" value="<?=e($v['source_url']??'')?>"><label>Порядок</label><input name="sort_order" type="number" min="-100000" max="100000" value="<?=e($v['sort_order']??0)?>"><label class="check"><input type="checkbox" name="is_published" value="1" <?=((int)($v['is_published']??0)===1)?'checked':''?>> Опубликовано</label><div class="actions"><button>Сохранить</button></div></form><?php if(is_array($edit)):?><form class="deletebox" method="post" action="/editor/?section=materials"><input type="hidden" name="action" value="delete_material"><input type="hidden" name="csrf_token" value="<?=e($csrfToken)?>"><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><label class="check"><input type="checkbox" name="confirm_delete" value="1" required> Подтверждаю удаление</label><div class="actions"><button class="danger">Удалить материал</button></div></form><?php endif;?></section></div>
<?php elseif($section==='events'):?><div class="split"><section class="panel"><h2>События</h2><p class="muted">Публичные даты работ и мероприятий.</p><div class="actions"><a class="button" href="/editor/?section=events&new=1">Добавить событие</a></div><div class="list"><?php foreach($events as $row):?><div class="row"><div><strong><?=e($row['title'])?></strong><small><?=e($row['event_date'])?> · <?=e($row['event_type'])?></small></div><div><span class="state"><?=((int)$row['is_published']===1)?'Опубликовано':'Черновик'?></span> · <a href="/editor/?section=events&edit=<?=(int)$row['id']?>">Изменить</a></div></div><?php endforeach;?><?php if($events===[]):?><div class="empty">Событий пока нет.</div><?php endif;?></div></section><section class="panel"><?php $v=is_array($edit)?$edit:[];?><h2><?=is_array($edit)?'Редактировать событие':'Новое событие'?></h2><form method="post" action="/editor/?section=events"><input type="hidden" name="action" value="save_event"><input type="hidden" name="csrf_token" value="<?=e($csrfToken)?>"><input type="hidden" name="id" value="<?=(int)($v['id']??0)?>"><label>Название</label><input name="title" maxlength="255" value="<?=e($v['title']??'')?>" required><label>Дата</label><input name="event_date" type="date" value="<?=e($v['event_date']??'')?>" required><label>Тип</label><select name="event_type"><option value="work" <?=($v['event_type']??'work')==='work'?'selected':''?>>Работа ложи</option><option value="feast" <?=($v['event_type']??'')==='feast'?'selected':''?>>Праздник</option><option value="other" <?=($v['event_type']??'')==='other'?'selected':''?>>Другое</option></select><label>Публичная заметка</label><textarea name="note"><?=e($v['note']??'')?></textarea><label class="check"><input type="checkbox" name="is_published" value="1" <?=((int)($v['is_published']??0)===1)?'checked':''?>> Опубликовано</label><div class="actions"><button>Сохранить</button></div></form><?php if(is_array($edit)):?><form class="deletebox" method="post" action="/editor/?section=events"><input type="hidden" name="action" value="delete_event"><input type="hidden" name="csrf_token" value="<?=e($csrfToken)?>"><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><label class="check"><input type="checkbox" name="confirm_delete" value="1" required> Подтверждаю удаление</label><div class="actions"><button class="danger">Удалить событие</button></div></form><?php endif;?></section></div>
<?php elseif($section==='pages'):?><div class="split"><section class="panel"><h2>Страницы</h2><p class="muted">Можно редактировать только заранее определённые страницы сайта.</p><div class="list"><?php foreach($pages as $row):?><div class="row"><div><strong><?=e($row['title'])?></strong><small><?=e($row['key'])?></small></div><div><span class="state"><?=((int)$row['is_published']===1)?'Опубликована':'Черновик'?></span> · <a href="/editor/?section=pages&edit=<?=e($row['key'])?>">Изменить</a></div></div><?php endforeach;?></div></section><section class="panel"><?php if(is_array($edit)):?><h2>Редактировать страницу</h2><form method="post" action="/editor/?section=pages"><input type="hidden" name="action" value="save_page"><input type="hidden" name="csrf_token" value="<?=e($csrfToken)?>"><input type="hidden" name="key" value="<?=e($edit['key'])?>"><p class="muted">Ключ: <?=e($edit['key'])?></p><label>Заголовок</label><input name="title" maxlength="255" value="<?=e($edit['title'])?>" required><label>Текст</label><textarea class="large" name="content" required><?=e($edit['content'])?></textarea><label class="check"><input type="checkbox" name="is_published" value="1" <?=((int)$edit['is_published']===1)?'checked':''?>> Опубликована</label><div class="actions"><button>Сохранить страницу</button></div></form><?php else:?><h2>Выберите страницу</h2><p class="muted">Создание новых страниц намеренно отключено, чтобы нельзя было случайно нарушить структуру сайта.</p><?php endif;?></section></div><?php endif;?>
